import {eventYoutubeId,eventYoutubeEmbed} from './event-youtube.js';
import {presentationForm,preparePresentationImage} from './presentation.js?v=event2';
import * as S from './shared-store.js?v=event2';
import { scheduleFields, resizeSchedule, readSchedule, posterFields } from './movie-form.js';
import { screeningsFor, validateScreenings } from './screenings.js';
import { preparePoster, validatePosterFile } from './poster.js';
import {esc as e,allowed,roles} from './util.js';
const sections={event:'Evento especial',presentation:'Cabecera y QR',movies:'Cartelera',candy:'Dulcería',upcoming:'Próximos estrenos',users:'Usuarios',settings:'Configuración / TMDB',backup:'Respaldos'};
const labels={date:'Fecha',time:'Hora',room:'Sala',title:'Título / nombre',year:'Año',rating:'Clasificación',price:'Precio MXN',free:'Entrada libre',synopsis:'Sinopsis',awards:'Premios y festivales',tmdb:'TMDB ID',poster:'Imagen / URL de póster',trailer:'URL de trailer',category:'Categoría',description:'Descripción',active:'Activo',label:'Etiqueta',name:'Correo de la cuenta de ChatGPT',pin:'PIN',role:'Rol',old:'PIN actual',next:'PIN nuevo',token:'API Read Access Token',query:'Título de búsqueda'};
const schema={movies:'title year rating price free synopsis awards tmdb trailer',candy:'title category price description poster active',upcoming:'title year date label tmdb trailer active'};
const options={role:roles,label:['PRÓXIMAMENTE','ESTRENO','PREESTRENO']};
function field(k,v='',required=false){const type={date:'date',time:'time',price:'number',year:'number',pin:'password',old:'password',next:'password',token:'password',active:'checkbox',free:'checkbox'}[k]||'text';let el=options[k]?'<select name="'+k+'">'+options[k].map(s=>'<option '+(v===s?'selected':'')+'>'+s+'</option>').join('')+'</select>':['synopsis','awards','description'].includes(k)?'<textarea name="'+k+'">'+e(v)+'</textarea>':'<input name="'+k+'" type="'+type+'" '+(type==='checkbox'?(v?'checked':''):'value="'+e(v)+'"')+' '+(required?'required':'')+' '+(k==='price'?'min="0" step=".01"':'')+'>';return '<label>'+e(labels[k])+el+'</label>'}
export function admin(refresh){const panel=document.querySelector('#panel'),out=document.querySelector('#private'),notice=document.querySelector('#notice');let tab='movies',action='',edit='',db,revision=0;
const message=s=>{notice.textContent=s;const status=out.querySelector('.presentationStatus');if(status)status.textContent=s},button=(id,title)=>'<button type="button" data-act="'+id+'">'+title+'</button>', vals=f=>Object.fromEntries(new FormData(f)),show=async(fn)=>{try{message('');await fn()}catch(err){message(err.message)}};
function logout(){S.logout();edit='';action='';tab='movies'}
panel.addEventListener('cancel',event=>{if(panel.inert)event.preventDefault()});
panel.addEventListener('close',()=>{logout();out.replaceChildren();message('')});
function open(){if(location.origin!==S.base){location.href=S.base+'/?admin=1';return}if(!panel.open)panel.showModal();show(async()=>{await S.data();await render()})}
document.querySelector('#admin').onclick=open;document.querySelector('#close').onclick=()=>panel.close();document.addEventListener('keydown',ev=>{if(ev.key==='F2'){ev.preventDefault();open()}});
function loginView(){if(S.shared){out.innerHTML='<h3>Administración compartida</h3><p>Entra con tu cuenta de ChatGPT. El propietario debe autorizar previamente el correo de cada apoyo en Usuarios.</p><p><a href="/signin-with-chatgpt?return_to=%2F%3Fadmin%3D1" target="_top">Iniciar sesión con ChatGPT</a></p>';return}const first=!S.cloud&&!S.accounts().length;out.innerHTML=(S.cloud?'':'<p><strong>Edición local: los cambios de este panel no se publican en el lobby.</strong> Descarga tu respaldo para publicarlo. La pantalla muestra la última cartelera publicada.</p>')+'<h3>'+(first?'Configurar este navegador':action==='users'?'Acceso de Administrador':action==='pin'?'Identifícate para cambiar tu acceso':'Acceso a la cabina')+'</h3><p>'+(first?'Crea tu usuario administrador y un PIN de 6 a 12 dígitos.':S.cloud?'Usa tu correo y contraseña de Supabase.':'Ingresa tu usuario y PIN local.')+'</p><form id="login"><div class="fields">'+field('name','',true)+field('pin','',true)+'</div><div class="actions"><button>'+(first?'Crear administrador':'Entrar')+'</button></div></form>'+button('usersLogin','+ Gestionar usuarios')+' '+button('pinLogin','Cambiar mi PIN')}
async function render(){const rev=++revision;const u=S.me();if(!u){loginView();return}db=await S.data();if(rev!==revision||!panel.open)return;const available=Object.keys(sections).filter(k=>k==='event'?u.role==='Administrador':allowed(u.role,k)||u.role==='Consulta'&&S.tables.includes(k));if(!available.includes(tab))tab=available[0];const tabs=available.map(k=>'<button type="button" data-tab="'+k+'" aria-pressed="'+(tab===k)+'">'+sections[k]+'</button>').join('');out.innerHTML='<div class="actions"><strong>'+e(u.name)+' · '+e(u.role)+'</strong>'+(S.shared?'':button('pin','Cambiar mi '+(S.cloud?'contraseña':'PIN')))+button('logout','Salir')+'</div><nav class="tabs">'+tabs+'</nav><div id="body"></div>';const body=out.querySelector('#body');if(action==='pin'){body.innerHTML='<form id="change">'+field('old','',true)+field('next','',true)+'<button>Guardar cambio</button></form>';return}
if(tab==='event'){const event=db.specialEvent||{};body.innerHTML='<h3>Evento especial</h3><p>Estado: <strong>'+(event.active?'ACTIVO · '+e(event.title):'Cartelera habitual')+'</strong></p><p>Ocupa toda la pantalla hasta finalizarlo. Imágenes JPG, PNG o WebP; video MP4 (H.264) o WebM sin sonido, en repetición. Máximo 50 MB. Recomendado: 1920 × 1080 píxeles. Otras proporciones conservan márgenes.</p><form id="specialEvent"><label>Nombre del evento<input name="title" maxlength="120" value="'+e(event.title||'')+'"></label><label>Contenido del evento<select name="source"><option value="file" '+(event.source!=='youtube'?'selected':'')+'>Imagen o video de mi computadora</option><option value="youtube" '+(event.source==='youtube'?'selected':'')+'>Enlace de YouTube</option></select></label><label>Enlace de YouTube<input name="youtubeUrl" type="url" placeholder="https://www.youtube.com/watch?v=…" value="'+e(event.youtubeUrl||'')+'"></label><p>Para YouTube selecciona Enlace de YouTube y pega un video. Se repetirá desde el principio, sin sonido. El video debe permitir reproducción en otras páginas; requiere internet.</p><label>Imagen o video<input name="media" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></label><p class="presentationStatus" role="status">Selecciona y revisa el archivo antes de iniciar. El lobby recibe el cambio en un máximo de 30 segundos.</p><div id="eventPreview"></div><button type="button" data-act="previewYoutube">Probar enlace de YouTube aquí</button><button name="eventAction" value="start">Iniciar evento especial</button> <button name="eventAction" value="stop">Finalizar evento y volver a cartelera</button></form>';return}
if(tab==='presentation'){body.innerHTML=presentationForm(db.presentation);return}
if(S.tables.includes(tab)){const record=db[tab].find(x=>x.id===edit)||{active:true},can=allowed(u.role,tab);body.innerHTML='<h3>'+sections[tab]+'</h3>'+(can?'<form id="entry"><div class="fields">'+schema[tab].split(' ').map(k=>field(k,record[k],['date','time','room','title'].includes(k))).join('')+'</div>'+(tab==='movies'?scheduleFields(record):'')+(tab!=='candy'?posterFields(record.poster):'')+'<div class="actions"><button>'+(edit?'Guardar cambios':'Agregar')+'</button>'+button('cancel','Cancelar edición')+'</div></form>'+(tab!=='candy'?'<details><summary>Buscar película en TMDB</summary><form id="lookup"><div class="fields">'+field('query','',true)+field('year')+'</div><button>Buscar</button></form><div id="results"></div></details>':''):'')+db[tab].map(x=>row(x,tab==='movies'?screeningsFor(x).map(f=>[f.date,f.time,f.room].join(' · ')).join(' / '):[x.date,x.active===false?'Inactivo':''].filter(Boolean).join(' · '),can)).join('');return}
if(tab==='users'){if(S.shared){const x=S.accounts().find(y=>y.id===edit)||{active:true,role:'Consulta'};body.innerHTML='<h3>Personas autorizadas</h3><p>Cada persona entra con su propia cuenta de ChatGPT. Usa el correo exacto de esa cuenta. El propietario conserva siempre el acceso.</p><form id="user"><div class="fields">'+['name','role','active'].map(k=>field(k,x[k],k==='name')).join('')+'</div><button>Guardar acceso</button></form>'+S.accounts().map(x=>row(x,x.role+(x.active?'':' · Inactivo'),true)).join('');return}if(S.cloud){body.innerHTML='<p>Administra las altas, bajas y contraseñas en Supabase Authentication. Asigna roles y activa perfiles en la tabla profiles.</p>';return}const x=S.accounts().find(y=>y.id===edit)||{active:true,role:'Consulta'};body.innerHTML='<form id="user"><div class="fields">'+['name','role','pin','active'].map(k=>field(k,x[k],k==='name'||k==='pin'&&!edit)).join('')+'</div><div class="actions"><button>'+(edit?'Guardar usuario':'Agregar usuario')+'</button>'+button('cancel','Cancelar edición')+'</div></form><details><summary>Alta múltiple</summary><form id="bulk"><label>Una línea por persona: usuario | rol | PIN<textarea name="rows" required></textarea></label><p>Roles: '+roles.join(', ')+'</p><button>Crear usuarios</button></form></details>'+S.accounts().map(x=>row(x,x.role+(x.active?'':' · Inactivo'),true)).join('')}
if(tab==='settings')body.innerHTML='<h3>Configuración de TMDB</h3><p>El token se conserva únicamente en esta pestaña. Deja el campo vacío para retirarlo.</p><form id="settings">'+field('token')+'<button>Guardar token</button></form><p>Modo '+(S.shared?'compartido en línea':S.cloud?'nube':'local')+'</p>';
if(tab==='backup')body.innerHTML='<h3>Respaldos de contenido</h3><p>Incluye funciones, dulcería y próximos estrenos. Los usuarios y sus accesos se administran por separado.</p>'+button('export','Descargar JSON')+(S.cloud||S.shared?'':'<form id="import"><label>Restaurar archivo JSON<input type="file" name="file" accept=".json" required></label><button>Restaurar respaldo</button></form>')}
function row(x,meta,can){return '<div class="row"><span><b>'+e(x.title||x.name)+'</b> '+e(meta)+'</span>'+(can?'<button data-edit="'+e(x.id)+'">Editar</button><button data-delete="'+e(x.id)+'">Eliminar</button>':'')+'</div>'}
out.addEventListener('click',ev=>show(async()=>{const b=ev.target.closest('button');if(!b)return;const a=b.dataset.act;if(a==='previewYoutube'){const id=eventYoutubeId(out.querySelector('[name=youtubeUrl]').value);if(!id)throw Error('Pega un enlace válido a un video de YouTube.');const box=out.querySelector('#eventPreview'),frame=document.createElement('iframe');frame.src=eventYoutubeEmbed(id,location.origin);frame.title='Vista previa de YouTube';frame.allow='autoplay; encrypted-media; fullscreen';frame.referrerPolicy='strict-origin-when-cross-origin';frame.style.cssText='width:100%;height:300px;border:0';box.replaceChildren(frame);return}if(b.dataset.tab){tab=b.dataset.tab;edit=action='';await render()}if(b.dataset.edit){edit=b.dataset.edit;await render();out.querySelector('form input')?.focus()}if(b.dataset.delete&&confirm('¿Eliminar este registro?')){const id=b.dataset.delete;if(tab==='users')await S.userWrite([{id}],true);else await S.write(tab,{id},true);edit='';await refresh();await render()}if(a==='cancel'){edit='';await render()}if(a==='logout'){if(S.shared){location.href='/signout-with-chatgpt?return_to=%2F';return}logout();await render()}if(a==='usersLogin'||a==='pinLogin'||a==='pin'){action=a==='usersLogin'?'users':'pin';await render()}if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='cinema-ccu-respaldo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}));
out.addEventListener('change', ev => {
  if(ev.target.name==='media'){const f=ev.target.files[0],box=out.querySelector('#eventPreview');box.replaceChildren();if(!f)return;const url=URL.createObjectURL(f),el=document.createElement(f.type.startsWith('video/')?'video':'img');el.src=url;el.style.cssText='max-width:100%;max-height:240px';if(el.tagName==='VIDEO'){el.controls=true;el.muted=true;el.onloadeddata=()=>URL.revokeObjectURL(url)}else el.onload=()=>URL.revokeObjectURL(url);el.onerror=()=>{URL.revokeObjectURL(url);message('No se puede reproducir este archivo. Prueba MP4 con H.264.');};box.append(el);}
  if (['bannerFile' ,'qrFile'].includes(ev.target.name)) { const input=ev.target,file=input.files[0];if(file){try{validatePosterFile(file);const preview=input.form.querySelector('.'+input.name.replace('File','')+'Preview');const url=URL.createObjectURL(file);preview.onload=preview.onerror=()=>URL.revokeObjectURL(url);preview.src=url;message('Vista previa lista. Pulsa Publicar cabecera y QR para actualizar el lobby.')}catch(error){input.value='';message(error.message)}}}
  if (ev.target.name === 'screeningCount') resizeSchedule(ev.target.form);
  if (ev.target.name === 'posterFile') {
    const input = ev.target;
    const file = input.files[0];
    if (!file) return;
    try {
      validatePosterFile(file);
      const preview = input.form.querySelector('.posterPreview');
      const url = URL.createObjectURL(file);
      preview.onload = preview.onerror = () => URL.revokeObjectURL(url);
      preview.src = url;
      message('Póster seleccionado. Guarda la ficha para conservarlo.');
    } catch (error) {
      input.value = '';
      message(error.message);
    }
  }
});
if(new URLSearchParams(location.search).get('admin')==='1')open();
let matches=[];
out.addEventListener('submit',ev=>{ev.preventDefault();const submitted=ev.target,removeImage=ev.submitter?.dataset.removeImage,eventAction=ev.submitter?.value;if(submitted.dataset.saving)return;submitted.dataset.saving='true';show(async()=>{const f=submitted,v=vals(f);panel.inert=true;if(f.id==='login'){if(!S.cloud&&!S.accounts().length)await S.init(v.name,v.pin);else await S.login(v.name,v.pin);if(action==='users'){if(S.me().role!=='Administrador'){logout();throw Error('Se requiere un Administrador.')}tab='users';action=''}await render();return}
if(f.id==='specialEvent'){
 message(eventAction==='stop'?'Finalizando evento…':'Subiendo y publicando evento…');
 if(eventAction==='stop')await S.saveEvent({active:false});else if(v.source==='youtube'){if(!eventYoutubeId(v.youtubeUrl))throw Error('Pega un enlace válido a un video de YouTube.');await S.saveEvent({active:true,source:'youtube',youtubeUrl:v.youtubeUrl,title:v.title})}else{
 const file=f.elements.media.files[0];let media=db.specialEvent;
 if(file){if(file.size>50*1024*1024)throw Error('Máximo 50 MB.');if(!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(file.type))throw Error('Formato no compatible.');media=await S.uploadEvent(file)}
 if(!media?.key)throw Error('Selecciona una imagen o video.');await S.saveEvent({active:true,key:media.key,title:v.title});
 }
}
else if(f.id==='presentation'){message('Publicando y verificando la imagen…');const p={...db.presentation,bannerEnabled:f.elements.bannerEnabled.checked,qrEnabled:f.elements.qrEnabled.checked,bannerAlt:v.bannerAlt,qrLabel:v.qrLabel,qrUrl:v.qrUrl};if(removeImage){Object.assign(p,db.presentation);p[removeImage+'Image']='';p[removeImage+'Enabled']=false}else{for(const kind of ['banner','qr']){const file=f.elements[kind+'File'].files[0];if(file){p[kind+'Image']=await preparePresentationImage(file,kind);p[kind+'Enabled']=true}}}await S.savePresentation(p)}
else if(f.id==='entry'){for(const k of ['active','free'])if(f.elements[k])v[k]=f.elements[k].checked;if('price'in v){if(!v.free&&v.price==='')throw Error('Indica el precio.');v.price=v.free?0:Number(v.price)}if (tab === 'movies') {
  v.screenings = readSchedule(f);
  validateScreenings(v.screenings);
  Object.assign(v, v.screenings[0]);
  for (const key of Object.keys(v)) {
    if (key === 'screeningCount' || key.startsWith('screening_')) delete v[key];
  }
}
if (tab !== 'candy') {
  const file = f.elements.posterFile.files[0];
  if (file) v.poster = await preparePoster(file);
  else if (f.elements.removePoster.checked) v.poster = '';
  else v.poster = v.poster.trim() || v.savedPoster;
  delete v.posterFile;
  delete v.savedPoster;
  delete v.removePoster;
}
if(edit)v.id=edit;await S.write(tab,v);edit=''}
else if(f.id==='user'){await S.userWrite([{...v,id:edit||undefined,active:f.elements.active.checked}]);edit=''}
else if(f.id==='bulk'){const rows=v.rows.trim().split(/\r?\n/).map(l=>{const a=l.split('|').map(s=>s.trim());if(a.length!==3)throw Error('Revisa el formato de cada línea.');return {name:a[0],role:a[1],pin:a[2],active:true}});await S.userWrite(rows)}
else if(f.id==='change'){await S.pinChange(v.old,v.next);action=''}
else if(f.id==='settings'){if(v.token)sessionStorage.setItem('ccu-tmdb',v.token.trim());else sessionStorage.removeItem('ccu-tmdb')}
else if(f.id==='import'){if(!confirm('¿Reemplazar todo el contenido local por este respaldo?'))return;S.restore(JSON.parse(await f.elements.file.files[0].text()))}
else if(f.id==='lookup'){const params=new URLSearchParams({query:v.query,language:'es-MX'});if(v.year)params.set('year',v.year);matches=(await tmdb('/search/movie?'+params)).results;const box=out.querySelector('#results');box.replaceChildren();if(!matches.length)box.textContent='Sin coincidencias.';for(const m of matches.slice(0,12)){const b=document.createElement('button');b.type='button';b.textContent=m.title+' · '+(m.release_date||'');b.onclick=()=>show(async()=>{const entry=out.querySelector('#entry');let videos=(await tmdb('/movie/'+m.id+'/videos?language=es-MX')).results;if(!videos.length)videos=(await tmdb('/movie/'+m.id+'/videos?language=en-US')).results;const clip=videos.filter(x=>x.site==='YouTube').sort((a,b)=>Number(b.type==='Trailer')-Number(a.type==='Trailer'))[0];for(const [k,w] of Object.entries({title:m.title,year:m.release_date?.slice(0,4),tmdb:m.id,poster:m.poster_path?'https://image.tmdb.org/t/p/w780'+m.poster_path:'',synopsis:m.overview,trailer:clip?'https://youtu.be/'+clip.key:''}))if(entry.elements[k])entry.elements[k].value=w||'';message('Ficha cargada. Revisa y guarda los cambios.')});box.append(b)}return}
await refresh();await render();message(f.id==='presentation'?(removeImage?'Imagen quitada y eliminación verificada. El lobby se actualizará en un máximo de 30 segundos.':'Cabecera y QR guardados y verificados. El lobby se actualizará en un máximo de 30 segundos.'):S.shared||S.cloud?'Cambios publicados. El lobby se actualizará en un máximo de 30 segundos.':'Borrador local.')} ).finally(()=>{panel.inert=false;delete submitted.dataset.saving});});
async function tmdb(path){const t=sessionStorage.getItem('ccu-tmdb');if(!t)throw Error('Configura el token TMDB en esta pestaña.');const r=await fetch('https://api.themoviedb.org/3'+path,{headers:{Authorization:'Bearer '+t}});if(!r.ok)throw Error('Consulta TMDB rechazada ('+r.status+').');return r.json()}}
